27	func TestReviseBasicAndHistory(t *testing.T) {
28		s := openTestStore(t)
29		reg(t, s, "A-001", "合同", "2020-01-01", "2025-01-10")
30	
31		rec := revise(t, s, "R-1", "A-001", "2025-01-10", "2026-02-20", "2024-12-01", " 业务需要 ")
32		if rec.RevisionID != "R-1" || rec.ArchiveID != "A-001" ||
