34			!rec.NewEnd.Equal(MustParseDate("2026-02-20")) ||
35			!rec.RevisedOn.Equal(MustParseDate("2024-12-01")) ||
36			rec.Reason != "业务需要" {
37			t.Fatalf("返回的修订记录不符: %+v", rec)
38		}
39	
40		// 再次修订（缩短），基于新的当前截止日。
41		revise(t, s, "R-2", "A-001", "2026-02-20", "2025-06-30", "2025-01-05", "重新评估")
42	
43		h, found, err := s.History("A-001")
44		if err != nil || !found {
45			t.Fatalf("核对历史失败: found=%v err=%v", found, err)
46		}
47		if !h.InitialEnd.Equal(MustParseDate("2025-01-10")) {
48			t.Fatalf("最初截止日应为登记值，得到 %s", h.InitialEnd)
49		}
50		if !h.RetentionEnd.Equal(MustParseDate("2025-06-30")) {
51			t.Fatalf("当前截止日应为最后一次修订值，得到 %s", h.RetentionEnd)
52		}
53		if len(h.Revisions) != 2 {
54			t.Fatalf("应有两条修订记录，得到 %d", len(h.Revisions))
55		}
56		first, second := h.Revisions[0], h.Revisions[1]
57		if first.RevisionID != "R-1" || !first.OldEnd.Equal(MustParseDate("2025-01-10")) ||
58			!first.NewEnd.Equal(MustParseDate("2026-02-20")) || first.Reason != "业务需要" {
59			t.Fatalf("第一条修订记录不符: %+v", first)
60		}
61		if second.RevisionID != "R-2" || !second.OldEnd.Equal(MustParseDate("2026-02-20")) ||
62			!second.NewEnd.Equal(MustParseDate("2025-06-30")) {
63			t.Fatalf("第二条修订记录不符: %+v", second)
64		}
65	}
66	
67	func TestReviseValidation(t *testing.T) {
68		s := openTestStore(t)
69		reg(t, s, "A-001", "合同", "2020-01-01", "2025-01-10")
70	
71		valid := ReviseInput{
72			RevisionID:  "R-1",
73			ArchiveID:   "A-001",
74			OriginalEnd: MustParseDate("2025-01-10"),
75			NewEnd:      MustParseDate("2026-01-10"),
76			RevisedOn:   MustParseDate("2024-12-01"),
77			Reason:      "延长",
78		}
79	
80		// 空白编号与原因（含纯空格）。
81		for _, blank := range []string{"", "  ", "\t"} {
82			in := valid
83			in.RevisionID = blank
84			if err := mustReviseErr(s, in); !errors.Is(err, ErrBlankField) {
85				t.Fatalf("空白修订编号应失败，得到 %v", err)
86			}
87			in = valid
88			in.Reason = blank
89			if err := mustReviseErr(s, in); !errors.Is(err, ErrBlankField) {
90				t.Fatalf("空白修订原因应失败，得到 %v", err)
91			}
92		}
93	
94		// 日期缺失或无效。
95		in := valid
96		in.NewEnd = Date{}
97		if err := mustReviseErr(s, in); !errors.Is(err, ErrInvalidDate) {
98			t.Fatalf("新截止日缺失应失败，得到 %v", err)
99		}
100		in = valid
101		in.OriginalEnd = Date{}
102		if err := mustReviseErr(s, in); !errors.Is(err, ErrInvalidDate) {
103			t.Fatalf("原截止日缺失应失败，得到 %v", err)
104		}
105		in = valid
106		in.RevisedOn = Date{}
107		if err := mustReviseErr(s, in); !errors.Is(err, ErrInvalidDate) {
108			t.Fatalf("修订日期缺失应失败，得到 %v", err)
109		}
110	
111		// 新截止日等于所提交的原截止日。
112		in = valid
113		in.NewEnd = in.OriginalEnd
114		if err := mustReviseErr(s, in); !errors.Is(err, ErrRevisionEndUnchanged) {
115			t.Fatalf("新截止日等于原截止日应失败，得到 %v", err)
116		}
117	
118		// 新截止日早于起算日（等于起算日合法）。
119		in = valid
120		in.NewEnd = MustParseDate("2019-12-31")
121		if err := mustReviseErr(s, in); !errors.Is(err, ErrRetentionEndBeforeStart) {
122			t.Fatalf("新截止日早于起算日应失败，得到 %v", err)
123		}
124		in = valid
125		in.NewEnd = MustParseDate("2020-01-01")
126		if _, err := s.Revise(in); err != nil {
127			t.Fatalf("新截止日等于起算日应允许，得到 %v", err)
128		}
129	
130		// 档案不存在。
131		in = valid
132		in.RevisionID = "R-2"
133		in.ArchiveID = "A-404"
134		if err := mustReviseErr(s, in); !errors.Is(err, ErrNotFound) {
135			t.Fatalf("档案不存在应失败 ErrNotFound，得到 %v", err)
136		}
137	
138		// 全部失败都不留下修订历史，期限不变。
139		h, _, _ := s.History("A-001")
140		if len(h.Revisions) != 1 || !h.RetentionEnd.Equal(MustParseDate("2020-01-01")) {
141			t.Fatalf("失败不应留下历史或改变期限: %+v", h)
142		}
143	}
144	
145	func mustReviseErr(s *Store, in ReviseInput) error {
146		_, err := s.Revise(in)
147		if err == nil {
148			return nil
149		}
150		return err
151	}
152	
153	func TestReviseEndChanged(t *testing.T) {
154		s := openTestStore(t)
155		reg(t, s, "A-001", "合同", "2020-01-01", "2025-01-10")
156		revise(t, s, "R-1", "A-001", "2025-01-10", "2026-01-10", "2024-12-01", "延长")
157	
158		// 仍按旧截止日提交：期限已变化，错误带当前截止日。
159		_, err := s.Revise(ReviseInput{
160			RevisionID:  "R-2",
161			ArchiveID:   "A-001",
162			OriginalEnd: MustParseDate("2025-01-10"),
163			NewEnd:      MustParseDate("2027-01-10"),
164			RevisedOn:   MustParseDate("2024-12-02"),
165			Reason:      "再延长",
166		})
167		if !errors.Is(err, ErrRetentionEndChanged) {
168			t.Fatalf("应返回期限已变化错误，得到 %v", err)
169		}
170		var changed *RetentionEndChangedError
171		if !errors.As(err, &changed) {
172			t.Fatalf("错误应为 RetentionEndChangedError，得到 %T", err)
173		}
174		if !changed.CurrentEnd.Equal(MustParseDate("2026-01-10")) {
175			t.Fatalf("错误应带当前截止日 2026-01-10，得到 %s", changed.CurrentEnd)
176		}
177	
178		// 失败不改变期限、不留历史。
179		h, _, _ := s.History("A-001")
180		if len(h.Revisions) != 1 || !h.RetentionEnd.Equal(MustParseDate("2026-01-10")) {
181			t.Fatalf("失败后状态不应变化: %+v", h)
182		}
183	
184		// 失败过的编号可重新提交（按当前截止日）。
185		revise(t, s, "R-2", "A-001", "2026-01-10", "2027-01-10", "2024-12-02", "再延长")
186	}
