176		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"}}); !errors.Is(err, ErrActiveFreeze) {
177			t.Fatalf("截止日当天视为到期，但冻结应阻止销毁，得到 %v", err)
178		}
179		// 解除后，截止日当天可以销毁。
180		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-10")}); err != nil {
181			t.Fatalf("解除失败: %v", err)
182		}
183		m, err := s.Destroy(DestructionRequest{ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"}})
184		if err != nil {
185			t.Fatalf("到期且无冻结应销毁成功，得到 %v", err)
186		}
187		if m.ApplicationID != "APP-1" || len(m.Entries) != 1 || m.Entries[0].ID != "A-1" {
188			t.Fatalf("清册内容不正确: %+v", m)
189		}
190	
191		// 销毁后不能再新增冻结，也不能再次销毁。
192		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "迟来", FrozenOn: MustParseDate("2025-01-11")}); !errors.Is(err, ErrDestroyed) {
193			t.Fatalf("销毁后新增冻结应失败，得到 %v", err)
194		}
195		if _, err := s.Destroy(DestructionRequest{ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-01-11"), ArchiveIDs: []string{"A-1"}}); !errors.Is(err, ErrArchiveAlreadyOnManifest) {
196			t.Fatalf("同一档案不能出现在两份清册中，得到 %v", err)
197		}
