1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上、已销毁档案仍带未解除冻结、已关闭清册缺少处理日期、清册处理
40	// 日期早于所收录档案销毁时最终生效的保管截止日（提前销毁）、已关闭清册
41	// 条目保存的类别、起算日或截止日（须为销毁时最终生效的期限）与档案登记
42	// 内容不一致、修订记录衔接不上、成功修订编号在保存历史中不唯一或与已关闭
43	// 清册的申请编号相同）时返回 ErrCorruptState，不会返回可继续办理的保管库，
44	// 已有记录保持原样，不会被清空、修补或覆盖。
45	func Open(dir string) (*Store, error) {
46		if dir == "" {
47			return nil, errors.New("retention: 保存位置不能为空")
48		}
49		if err := os.MkdirAll(dir, 0o755); err != nil {
50			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
51		}
52		s := &Store{dir: dir}
53		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
54		if _, err := s.load(); err != nil {
55			return nil, err
56		}
57		return s, nil
58	}
59	
60	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
61	func (s *Store) Close() error { return nil }
62	
63	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
64	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
65	
66	// lock 取得跨进程排他锁，返回解锁函数。
67	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
68	func (s *Store) lock() (func(), error) {
69		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
70		if err != nil {
71			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
72		}
73		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
74			f.Close()
75			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
76		}
77		return func() {
78			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
79			_ = f.Close()
80		}, nil
81	}
82	
83	// rlock 取得跨进程共享锁，用于只读核对。
84	func (s *Store) rlock() (func(), error) {
85		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
86		if err != nil {
87			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
88		}
89		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
90			f.Close()
91			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
92		}
93		return func() {
94			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
95			_ = f.Close()
96		}, nil
97	}
98	
99	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
100	//
101	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
102	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
103	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
104	// 绝不只使用前一段内容，也不会改动原文件。
105	//
106	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
107	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
108	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
109	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
110	//
111	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
112	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
113	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
114	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
115	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
116	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
117	//
118	// 归属对应之外，冻结状态也必须与销毁记录一致：仍被冻结的档案不能销毁，
119	// 已销毁档案的全部冻结都应已合法解除；只要任一已销毁档案还有一条冻结仍
120	// 标记为未解除，即使清册归属、条目内容和处理日期都合法，销毁记录与冻结
121	// 状态也互相矛盾，整份保管库判为损坏并返回 ErrCorruptState，错误信息指明
122	// 档案编号、未解除的冻结编号与所属清册申请编号。同一档案其他冻结已解除
123	// 不能抵消这一条；残留的解除日期或解除原因也不能把仍标记为未解除的冻结
124	// 当作已解除——是否解除只看保存的解除标记。
125	//
126	// 仅归属对应还不够：已关闭清册中的每条档案条目是销毁成功那一刻登记内容
127	// 的快照，其类别、起算日、截止日必须与对应档案当前保存的登记内容逐项
128	// 一致。档案销毁后期限不能再修订，编号、类别与起算日也从不改动，所以
129	// 合法记录中两处必然相同；截止日必须是销毁时最终生效的期限（最后一次
130	// 成功修订的新截止日，没有修订时为最初登记的截止日），即使修订历史衔接
131	// 完整、清册归属正确，保存成最初登记的截止日也属损坏。任一条目在类别、
132	// 起算日、截止日任一项上不一致，两处记录就互相矛盾，整份保管库判为
133	// 损坏并返回 ErrCorruptState，错误信息指明清册申请编号、档案编号与
134	// 不一致的项目；绝不挑选其中一处作为可信记录，也不通过覆盖清册、修改
135	// 档案或删除记录消除差异。一份清册收录多份档案时，一份条目矛盾就使
136	// 整份保管库无法读取，不会返回其余条目的正常结果。
137	//
138	// 清册的处理日期也必须满足办理销毁时同一条到期规则：每份已关闭清册都必须
139	// 带有处理日期，且处理日期不能早于其任一条目档案销毁时最终生效并保存到
140	// 清册里的截止日——截止日当天即到期，等于截止日或晚于截止日才合法。
141	// 缺少处理日期（字段缺失或为 null）不能当成已经办理的销毁日期；处理日期
142	// 早于某份档案的截止日属于提前销毁，即使该档案标记为已销毁、清册归属与
143	// 条目快照都一致，也说明销毁在到期前发生，两份记录无法同时成立。期限有过
144	// 修订的档案按清册条目保存的最终截止日判断（修订办理日期只记录办理时间，
145	// 不用它重新选择期限）。缺处理日期时错误指出申请编号；提前销毁时同时指出
146	// 申请编号、档案编号、处理日期与截止日。一份清册中只要有一份档案未到期，
147	// 整份保管库都判为损坏，不会只返回其余已到期档案的正常记录，也不会略过
148	// 未到期条目。
149	//
150	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
151	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
152	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
153	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
154	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
155	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
156	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
157	// 同时指明修订编号。
158	//
159	// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
160	// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
161	// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
162	// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
163	// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
164	// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
165	// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
166	// 档案，与清册冲突时指出修订所属档案与清册申请编号。
167	func (s *Store) load() (*storeData, error) {
168		raw, err := os.ReadFile(s.statePath())
169		if err != nil {
170			if errors.Is(err, os.ErrNotExist) {
171				return newStoreData(), nil
172			}
173			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
174		}
175		trimmed := bytes.TrimSpace(raw)
176		if len(trimmed) == 0 {
177			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
178		}
179		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
180		if string(trimmed) == "null" {
181			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
182		}
183		data := newStoreData()
184		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
185		// 合法对象后面再拼接任何内容都会在这里报错。
186		if err := json.Unmarshal(raw, data); err != nil {
187			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
188		}
189		if data.Archives == nil {
190			data.Archives = map[string]*archiveRecord{}
191		}
192		if data.Manifests == nil {
193			data.Manifests = map[string]*manifestRecord{}
194		}
195		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
196		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
197		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
198		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
199		if err := validateFreezeReleaseRecords(data); err != nil {
200			return nil, err
201		}
202		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
203		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
204		if err := validateManifestConsistency(data); err != nil {
205			return nil, err
206		}
207		// 已销毁档案不能仍带未解除冻结：冻结挡住销毁是办理时的硬性规则，
208		// 销毁后的历史也必须满足。归属、条目与处理日期即使都合法，这项矛盾
209		// 仍使整库记录不可信。
210		if err := validateDestroyedArchiveFreezes(data); err != nil {
211			return nil, err
212		}
213		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
214		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
215		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
216		for _, ar := range data.Archives {
217			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
218				ar.InitialEnd = ar.End
219			}
220		}
221		// 已关闭清册中的每条档案条目是销毁成功那一刻的登记内容快照，
222		// 其类别、起算日与截止日必须与对应档案保存的登记内容逐项一致，
223		// 截止日必须是该档案销毁时最终生效的期限，不能拿最初登记的截止日顶替。
224		if err := validateManifestSnapshots(data); err != nil {
225			return nil, err
226		}
227		// 已关闭清册还必须带有处理日期，且处理日期不能早于任一条目档案销毁时
228		// 最终生效并保存到清册里的截止日——与办理销毁时的到期判断同一条规则。
229		if err := validateManifestProcessing(data); err != nil {
230			return nil, err
231		}
232		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
233		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
234		if err := validateRevisionContinuity(data); err != nil {
235			return nil, err
236		}
237		// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
238		// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
239		if err := validateRevisionIDs(data); err != nil {
240			return nil, err
241		}
242		return data, nil
243	}
244	
245	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
246	//
247	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
248	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
249	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
250	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
251	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
252	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
253	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
254	func validateFreezeReleaseRecords(data *storeData) error {
255		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
256		archiveIDs := make([]string, 0, len(data.Archives))
257		for id := range data.Archives {
258			archiveIDs = append(archiveIDs, id)
259		}
260		sort.Strings(archiveIDs)
261		for _, id := range archiveIDs {
262			ar := data.Archives[id]
263			if ar == nil {
264				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
265					id, ErrCorruptState)
266			}
267			for _, fr := range ar.Freezes {
268				if fr == nil {
269					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
270						id, ErrCorruptState)
271				}
272				if !fr.Released {
273					// 未解除冻结没有解除日期与原因是合法状态。
274					continue
275				}
276				switch {
277				case strings.TrimSpace(fr.ReleaseReason) == "":
278					return fmt.Errorf(
279						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
280						id, fr.ID, ErrCorruptState)
281				case fr.ReleasedOn == nil:
282					return fmt.Errorf(
283						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
284						id, fr.ID, ErrCorruptState)
285				case fr.ReleasedOn.IsZero():
286					return fmt.Errorf(
287						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
288						id, fr.ID, ErrCorruptState)
289				case fr.ReleasedOn.Before(fr.FrozenOn):
290					return fmt.Errorf(
291						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
292						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
293				}
294			}
295		}
296		return nil
297	}
298	
299	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
300	//
301	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
302	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
303	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
304	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
305	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
306	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
307	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
308	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
309	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
310	func validateManifestConsistency(data *storeData) error {
311		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
312		archiveIDs := make([]string, 0, len(data.Archives))
313		for id := range data.Archives {
314			archiveIDs = append(archiveIDs, id)
315		}
316		sort.Strings(archiveIDs)
317		for _, id := range archiveIDs {
318			ar := data.Archives[id]
319			if ar == nil {
320				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
321				continue
322			}
323			if !ar.Destroyed {
324				if ar.ManifestID != "" {
325					return fmt.Errorf(
326						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
327						id, ar.ManifestID, ErrCorruptState)
328				}
329				continue
330			}
331			if ar.ManifestID == "" {
332				return fmt.Errorf(
333					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
334					id, ErrCorruptState)
335			}
336			rec, ok := data.Manifests[ar.ManifestID]
337			if !ok || rec == nil {
338				return fmt.Errorf(
339					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
340					id, ar.ManifestID, ErrCorruptState)
341			}
342			count := 0
343			for _, e := range rec.Entries {
344				if e.ID == id {
345					count++
346				}
347			}
348			if count != 1 {
349				return fmt.Errorf(
350					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
351					id, ar.ManifestID, count, ErrCorruptState)
352			}
353		}
354	
355		applicationIDs := make([]string, 0, len(data.Manifests))
356		for id := range data.Manifests {
357			applicationIDs = append(applicationIDs, id)
358		}
359		sort.Strings(applicationIDs)
360		for _, appID := range applicationIDs {
361			rec := data.Manifests[appID]
362			if rec == nil {
363				return fmt.Errorf(
364					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
365					appID, ErrCorruptState)
366			}
367			seen := make(map[string]int, len(rec.Entries))
368			for _, e := range rec.Entries {
369				seen[e.ID]++
370				ar, ok := data.Archives[e.ID]
371				if !ok || ar == nil {
372					return fmt.Errorf(
373						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
374						appID, e.ID, ErrCorruptState)
375				}
376				if !ar.Destroyed {
377					return fmt.Errorf(
378						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
379						appID, e.ID, ErrCorruptState)
380				}
381				if ar.ManifestID != appID {
382					return fmt.Errorf(
383						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
384						appID, e.ID, ar.ManifestID, ErrCorruptState)
385				}
386			}
387			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
388			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
389			entryIDs := make([]string, 0, len(seen))
390			for id := range seen {
391				entryIDs = append(entryIDs, id)
392			}
393			sort.Strings(entryIDs)
394			for _, id := range entryIDs {
395				if seen[id] > 1 {
396					return fmt.Errorf(
397						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
398						appID, id, seen[id], ErrCorruptState)
399				}
400			}
401		}
402		return nil
403	}
404	
405	// validateDestroyedArchiveFreezes 检查已销毁档案是否仍带着未解除的冻结。
406	//
407	// 办理销毁时，任一未解除冻结都会阻止销毁（见 evaluateArchive），因此保存
408	// 下来的历史也必须满足同一条规则：每份已销毁档案的全部冻结都应已合法解除。
409	// 档案已标记为已销毁、所属清册存在且清册归属、条目快照与处理日期都合法，
410	// 但该档案仍有一条冻结标记为未解除（released 为 false）时，销毁记录与冻结
411	// 状态互相矛盾，两份记录无法同时成立，整份保管库判为损坏并返回
412	// ErrCorruptState，错误信息给出档案编号、未解除的冻结编号与所属清册的申请
413	// 编号，让调用者知道是哪份销毁记录与冻结状态冲突。
414	//
415	// 同一档案有多条冻结时，其他冻结已经解除不能抵消这一条阻碍，逐份档案只要
416	// 命中第一条未解除冻结即报错；即使这条记录里残留了解除日期或解除原因，只要
417	// 仍标记为未解除，就不能据此当作已解除——是否解除只沿用保存的解除标记判断，
418	// 解除日期与原因的合法性仍由 validateFreezeReleaseRecords 单独核对。
419	// 校验覆盖整个保管库的全部已销毁档案，与本次办理名单或查询目标无关：
420	// 一份清册收录多份档案，只有其中一份矛盾，或调用者只操作另一份正常档案时，
421	// 整份保管库同样判为损坏，绝不返回其余档案的正常结果。绝不通过自动解除冻结、
422	// 删除冻结历史、修改销毁标记或重建清册来消除冲突。
423	// 尚未销毁的档案保留未解除冻结是合法状态，不在此报错。
424	func validateDestroyedArchiveFreezes(data *storeData) error {
425		// map 遍历顺序不稳定，按档案编号排序、冻结按登记顺序检查，
426		// 保证错误信息稳定。
427		archiveIDs := make([]string, 0, len(data.Archives))
428		for id := range data.Archives {
429			archiveIDs = append(archiveIDs, id)
430		}
431		sort.Strings(archiveIDs)
432		for _, id := range archiveIDs {
433			ar := data.Archives[id]
434			if ar == nil || !ar.Destroyed {
435				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告；
436				// 尚未销毁的档案保留未解除冻结是合法状态。
437				continue
438			}
439			for _, fr := range ar.Freezes {
440				if fr == nil {
441					// 空冻结记录已由 validateFreezeReleaseRecords 报告。
442					continue
443				}
444				if !fr.Released {
445					// 归属关系已由 validateManifestConsistency 确认：
446					// 已销毁档案必然带有存在的所属清册申请编号。
447					return fmt.Errorf(
448						"retention: 档案 %s 已销毁（所属清册 %s），但冻结 %s 仍标记为未解除，冻结状态与销毁记录冲突，记录已损坏: %w",
449						id, ar.ManifestID, fr.ID, ErrCorruptState)
450				}
451			}
452		}
453		return nil
454	}
455	
456	// validateManifestSnapshots 检查每份已关闭清册中的档案条目是否与对应档案
457	// 当前保存的登记内容逐项一致。
458	//
459	// 清册在销毁成功那一刻关闭，条目是关闭瞬间登记内容的快照：档案销毁后
460	// 不能再修订期限，编号、类别与起算日也从不改动，因此合法记录中清册条目
461	// 的类别、起算日与截止日必然与对应档案保存的值相同——其中截止日必须是
462	// 该档案销毁时最终生效的期限（等于最后一次成功修订的新截止日；没有修订
463	// 时等于最初登记的截止日），不能拿最初登记的截止日顶替。延长、缩短或
464	// 改回曾经使用过的日期都沿用这一规则，不按修订记录中的办理日期重新选择。
465	//
466	// 任一条目在类别、起算日、截止日任一项上与档案不一致，两处记录就互相
467	// 矛盾，任何一处都不能当作可信依据：返回可由 ErrCorruptState 识别的错误，
468	// 绝不挑选其中一份继续使用，也不通过覆盖清册、修改档案或删除记录消除差异。
469	// 错误信息给出清册申请编号、档案编号与不一致的项目（类别、起算日、
470	// 保管截止日，并附上两处各自保存的值）。校验覆盖整个保管库的全部清册
471	// 与全部条目，与本次办理名单或查询目标无关：一份清册收录多份档案时，
472	// 只要有一份条目矛盾，整份保管库都判为损坏，不会返回其余条目的正常结果。
473	func validateManifestSnapshots(data *storeData) error {
474		// map 遍历顺序不稳定，按申请编号、条目顺序检查，保证错误信息稳定。
475		appIDs := make([]string, 0, len(data.Manifests))
476		for appID := range data.Manifests {
477			appIDs = append(appIDs, appID)
478		}
479		sort.Strings(appIDs)
480		for _, appID := range appIDs {
481			rec := data.Manifests[appID]
482			if rec == nil {
483				// 缺失的清册记录已由 validateManifestConsistency 报告。
484				continue
485			}
486			for _, e := range rec.Entries {
487				ar, ok := data.Archives[e.ID]
488				if !ok || ar == nil {
489					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
490					continue
491				}
492				items := make([]string, 0, 3)
493				if e.Category != ar.Category {
494					items = append(items, fmt.Sprintf("类别（清册 %q，档案 %q）", e.Category, ar.Category))
495				}
496				if !e.Start.Equal(ar.Start) {
497					items = append(items, fmt.Sprintf("起算日（清册 %s，档案 %s）", e.Start, ar.Start))
498				}
499				if !e.End.Equal(ar.End) {
500					items = append(items, fmt.Sprintf("保管截止日（清册 %s，档案 %s）", e.End, ar.End))
501				}
502				if len(items) > 0 {
503					return fmt.Errorf(
504						"retention: 清册 %s 中档案 %s 的条目与档案登记内容不一致：%s，记录已损坏: %w",
505						appID, e.ID, strings.Join(items, "、"), ErrCorruptState)
506				}
507			}
508		}
509		return nil
510	}
511	
512	// validateManifestProcessing 检查每份已关闭清册是否带有处理日期，以及处理日期
513	// 是否满足办理销毁时同一条到期规则。
514	//
515	// 办理销毁时，只有处理日期不早于名单中任一份档案当时生效的保管截止日才会成功
516	// （截止日当天即到期，见 evaluateArchive），清册条目保存的截止日正是销毁时
517	// 最终生效的期限（已由 validateManifestSnapshots 确认与档案当前登记一致）。
518	// 因此保存的清册还必须满足：
519	//   - 处理日期必须存在：清册缺少处理日期或保存为 null 时，不能把缺失日期当成
520	//     已经办理的销毁日期；
521	//   - 处理日期不能早于任一条目保存的截止日：等于截止日（当天）或晚于截止日
522	//     才合法。期限有过修订的档案按销毁时最终生效并保存到清册里的截止日判断，
523	//     延长、缩短或改回早先用过的日期都一样，绝不按修订办理日期重新挑选另一版期限。
524	//
525	// 缺少处理日期时返回可由 ErrCorruptState 识别的错误并指出清册申请编号；
526	// 处理日期早于某条档案的截止日时同样判为损坏，错误同时指出申请编号、档案编号、
527	// 处理日期与该档案的截止日。一份清册收录多份档案时，只要有一份尚未到期
528	// （例如处理日期等于第一份的截止日、却早于第二份的截止日），整份保管库都
529	// 判为损坏：不会只返回已到期条目的正常记录，也不会把未到期条目略过。校验
530	// 覆盖整个保管库的全部清册，与本次办理名单或查询目标无关；绝不通过改动档案
531	// 或清册（补处理日期、改期限、改销毁标记或条目）消除矛盾。
532	func validateManifestProcessing(data *storeData) error {
533		// map 遍历顺序不稳定，按申请编号排序、条目按清册内保存顺序检查，
534		// 保证错误信息稳定。
535		appIDs := make([]string, 0, len(data.Manifests))
536		for appID := range data.Manifests {
537			appIDs = append(appIDs, appID)
538		}
539		sort.Strings(appIDs)
540		for _, appID := range appIDs {
541			rec := data.Manifests[appID]
542			if rec == nil {
543				// 缺失的清册记录已由 validateManifestConsistency 报告。
544				continue
545			}
546			if rec.ProcessedOn == nil || rec.ProcessedOn.IsZero() {
547				return fmt.Errorf(
548					"retention: 清册 %s 缺少处理日期，不能视为已经办理的销毁清册，记录已损坏: %w",
549					appID, ErrCorruptState)
550			}
551			processedOn := *rec.ProcessedOn
552			for _, e := range rec.Entries {
553				ar, ok := data.Archives[e.ID]
554				if !ok || ar == nil {
555					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
556					continue
557				}
558				// 条目截止日已由 validateManifestSnapshots 确认与档案最终生效的
559				// 截止日一致，直接按保存在清册里的截止日判断到期。
560				if processedOn.Before(e.End) {
561					return fmt.Errorf(
562						"retention: 清册 %s 的处理日期 %s 早于档案 %s 的保管截止日 %s（截止日当天才算到期），属于提前销毁，记录已损坏: %w",
563						appID, processedOn, e.ID, e.End, ErrCorruptState)
564				}
565			}
566		}
567		return nil
568	}
569	
570	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
571	// 是否连续对应。
572	//
573	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
574	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
575	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
576	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
577	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
578	//
579	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
580	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
581	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
582	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
583	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
584	func validateRevisionContinuity(data *storeData) error {
585		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
586		archiveIDs := make([]string, 0, len(data.Archives))
587		for id := range data.Archives {
588			archiveIDs = append(archiveIDs, id)
589		}
590		sort.Strings(archiveIDs)
591		for _, id := range archiveIDs {
592			ar := data.Archives[id]
593			if ar == nil {
594				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
595				continue
596			}
597			if len(ar.Revisions) == 0 {
598				// 没有修订时最初截止日与当前截止日必须相同
599				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
600				if !ar.InitialEnd.Equal(ar.End) {
601					return fmt.Errorf(
602						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
603						id, ar.InitialEnd, ar.End, ErrCorruptState)
604				}
605				continue
606			}
607			for i, rec := range ar.Revisions {
608				if rec == nil {
609					return fmt.Errorf(
610						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
611						id, i+1, ErrCorruptState)
612				}
613			}
614			if ar.InitialEnd.IsZero() {
615				return fmt.Errorf(
616					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
617					id, ar.Revisions[0].ID, ErrCorruptState)
618			}
619			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
620			expected := ar.InitialEnd
621			for _, rec := range ar.Revisions {
622				if !rec.OldEnd.Equal(expected) {
623					return fmt.Errorf(
624						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
625						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
626				}
627				expected = rec.NewEnd
628			}
629			if !ar.End.Equal(expected) {
630				return fmt.Errorf(
631					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
632					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
633			}
634		}
635		return nil
636	}
637	
638	// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
639	// 清册申请编号的互不占用。
640	//
641	// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
642	// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
643	// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
644	// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
645	// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
646	// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
647	//
648	// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
649	// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
650	// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
651	// 作为成功记录存在，一并按损坏处理。
652	func validateRevisionIDs(data *storeData) error {
653		owners := make(map[string]string)
654		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
655		archiveIDs := make([]string, 0, len(data.Archives))
656		for id := range data.Archives {
657			archiveIDs = append(archiveIDs, id)
658		}
659		sort.Strings(archiveIDs)
660		for _, id := range archiveIDs {
661			ar := data.Archives[id]
662			if ar == nil {
663				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
664				continue
665			}
666			for _, rec := range ar.Revisions {
667				if rec == nil {
668					// 空记录已由 validateRevisionContinuity 报告。
669					continue
670				}
671				if strings.TrimSpace(rec.ID) == "" {
672					return fmt.Errorf(
673						"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
674						id, ErrCorruptState)
675				}
676				if owner, ok := owners[rec.ID]; ok {
677					if owner == id {
678						return fmt.Errorf(
679							"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
680							rec.ID, id, ErrCorruptState)
681					}
682					return fmt.Errorf(
683						"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
684						rec.ID, owner, id, ErrCorruptState)
685				}
686				owners[rec.ID] = id
687			}
688		}
689		// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
690		// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
691		appIDs := make([]string, 0, len(data.Manifests))
692		for appID := range data.Manifests {
693			appIDs = append(appIDs, appID)
694		}
695		sort.Strings(appIDs)
696		for _, appID := range appIDs {
697			if owner, ok := owners[appID]; ok {
698				return fmt.Errorf(
699					"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
700					owner, appID, appID, ErrCorruptState)
701			}
702		}
703		return nil
704	}
705	
706	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
707	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
708	func (s *Store) save(data *storeData) error {
709		buf, err := json.MarshalIndent(data, "", "  ")
710		if err != nil {
711			return fmt.Errorf("retention: 状态编码失败: %w", err)
712		}
713		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
714		if err != nil {
715			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
716		}
717		tmpName := tmp.Name()
718		cleanup := func() { _ = os.Remove(tmpName) }
719		if _, err := tmp.Write(buf); err != nil {
720			tmp.Close()
721			cleanup()
722			return fmt.Errorf("retention: 写入状态失败: %w", err)
723		}
724		if err := tmp.Sync(); err != nil {
725			tmp.Close()
726			cleanup()
727			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
728		}
729		if err := tmp.Close(); err != nil {
730			cleanup()
731			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
732		}
733		if err := os.Rename(tmpName, s.statePath()); err != nil {
734			cleanup()
735			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
736		}
737		// 刷目录，确保 rename 在崩溃后仍然落盘。
738		if dir, err := os.Open(s.dir); err == nil {
739			_ = dir.Sync()
740			_ = dir.Close()
741		}
742		return nil
743	}
744	
745	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
746	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
747	func (s *Store) mutate(fn func(*storeData) error) error {
748		s.opMu.Lock()
749		defer s.opMu.Unlock()
750		unlock, err := s.lock()
751		if err != nil {
752			return err
753		}
754		defer unlock()
755		data, err := s.load()
756		if err != nil {
757			return err
758		}
759		if err := fn(data); err != nil {
760			return err
761		}
762		return s.save(data)
763	}
764	
765	// view 在共享锁内重读状态并执行只读查询。
766	func (s *Store) view(fn func(*storeData) error) error {
767		s.opMu.RLock()
768		defer s.opMu.RUnlock()
769		unlock, err := s.rlock()
770		if err != nil {
771			return err
772		}
773		defer unlock()
774		data, err := s.load()
775		if err != nil {
776			return err
777		}
778		return fn(data)
779	}
