85	// MarshalJSON 按 YYYY-MM-DD 序列化。
86	func (d Date) MarshalJSON() ([]byte, error) {
87		return []byte(`"` + d.String() + `"`), nil
88	}
89	
90	// UnmarshalJSON 按 YYYY-MM-DD 形式反序列化并校验真实日期。
91	func (d *Date) UnmarshalJSON(data []byte) error {
92		if len(data) < 2 || data[0] != '"' || data[len(data)-1] != '"' {
93			return &InvalidDateError{Value: string(data)}
94		}
95		parsed, err := ParseDate(string(data[1 : len(data)-1]))
96		if err != nil {
97			return err
98		}
99		*d = parsed
100		return nil
101	}
102	
103	func writePadded(b *strings.Builder, value, width int) {
104		s := strconv.Itoa(value)
105		for i := len(s); i < width; i++ {
106			b.WriteByte('0')
107		}
108		b.WriteString(s)
109	}
