111	func validCalendarDate(year, month, day int) bool {
112		// 年份允许 0001..9999；月份、日期必须真实存在，含闰年规则。
113		if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 {
114			return false
115		}
116		daysInMonth := 31
117		switch month {
118		case 4, 6, 9, 11:
119			daysInMonth = 30
120		case 2:
121			leap := year%4 == 0 && (year%100 != 0 || year%400 == 0)
122			if leap {
123				daysInMonth = 29
124			} else {
125				daysInMonth = 28
126			}
127		}
128		return day <= daysInMonth
129	}
