	}
	if len(h1.Revisions) != 2 {
		t.Fatalf("A-1 应保留两次修订，得到 %d: %+v", len(h1.Revisions), h1.Revisions)
	}
	r1, r2 := h1.Revisions[0], h1.Revisions[1]
	if r1.RevisionID != "R-1" || !r1.OldEnd.Equal(initialEnd) || !r1.NewEnd.Equal(extendedEnd) ||
