110		// 办理日期只是记录信息，不决定哪次期限生效，仍采用最后一次成功
111		// 提交的新截止日 2025-01-10。
112		revise(t, s, "R-2", "A-1", "2025-03-10", "2025-01-10", "2024-12-01", "重新评估缩短")
113	
114		// 用原申请核对：当天算到期，报告恢复为可以办理。
115		readyAgain := mustCheck(t, s, "APP-1", "2025-01-10", ids...)
116		if readyAgain.Status != CheckReady {
117			t.Fatalf("缩短到处理日期当天后核对应恢复可以办理，得到 %s", readyAgain.Status)
118		}
119		if !readyAgain.Results[0].End.Equal(finalEnd) || len(readyAgain.Results[0].Obstructions) != 0 {
120			t.Fatalf("被修订档案应按最终截止日 %s 判定到期: %+v", finalEnd, readyAgain.Results[0])
121		}
122	
123		// 沿用原申请编号、处理日期和名单正式提交：整体成功，两份档案进入
124		// 同一份已关闭清册。
125		manifest, err := s.Destroy(DestructionRequest{
126			ApplicationID: "APP-1", ProcessedOn: processedOn, ArchiveIDs: ids,
127		})
128		if err != nil {
129			t.Fatalf("两份档案均到期且无冻结，正式提交应整体成功: %v", err)
130		}
131		if manifest.ApplicationID != "APP-1" || !manifest.ProcessedOn.Equal(processedOn) ||
132			len(manifest.Entries) != 2 {
133			t.Fatalf("应生成含两份条目的已关闭清册: %+v", manifest)
134		}
135		// 条目按编号排序；被修订条目的截止日是最终生效值，不能使用最初
136		// 登记值 2025-01-05 或中间延长过的 2025-03-10。
137		if manifest.Entries[0].ID != "A-1" || manifest.Entries[1].ID != "A-2" {
138			t.Fatalf("清册条目应按编号稳定排序: %+v", manifest.Entries)
139		}
140		e1 := manifest.Entries[0]
141		if e1.Category != "合同" || !e1.Start.Equal(MustParseDate("2020-01-01")) ||
142			!e1.End.Equal(finalEnd) {
143			t.Fatalf("A-1 清册条目应保存最终生效截止日 %s: %+v", finalEnd, e1)
144		}
145		if !manifest.Entries[1].End.Equal(MustParseDate("2025-01-10")) {
146			t.Fatalf("A-2 清册条目截止日不正确: %+v", manifest.Entries[1])
147		}
148	
149		// 调用者此前拿到的报告保留各自核对时的截止日与结论，不因后续修订
150		// 或销毁被改写。
151		if first.Status != CheckReady ||
152			!first.Results[0].End.Equal(initialEnd) || !first.Results[1].End.Equal(MustParseDate("2025-01-10")) ||
153			len(first.Results[0].Obstructions) != 0 || first.Manifest != nil {
154			t.Fatalf("首次报告被后续修订/销毁改写: %+v", first)
155		}
156		if blocked.Status != CheckBlocked || !blocked.Results[0].End.Equal(extendedEnd) ||
157			len(blocked.Results[0].Obstructions) != 1 ||
158			blocked.Results[0].Obstructions[0].Kind != ObstructionNotExpired ||
159			len(blocked.Results[1].Obstructions) != 0 || blocked.Manifest != nil {
160			t.Fatalf("存在阻碍报告被后续修订/销毁改写: %+v", blocked)
161		}
162		if readyAgain.Status != CheckReady || !readyAgain.Results[0].End.Equal(finalEnd) ||
163			len(readyAgain.Results[0].Obstructions) != 0 {
164			t.Fatalf("恢复可办的报告被后续销毁改写: %+v", readyAgain)
165		}
166	
167		// 新查询反映当前保存状态：按申请编号取回的就是关闭时那份清册。
168		got, found, err := s.GetManifest("APP-1")
169		if err != nil || !found {
170			t.Fatalf("成功提交后应能取回清册: found=%v err=%v", found, err)
171		}
172		if got.ApplicationID != manifest.ApplicationID || !got.ProcessedOn.Equal(manifest.ProcessedOn) ||
173			len(got.Entries) != 2 || !got.Entries[0].End.Equal(finalEnd) {
174			t.Fatalf("新查询的清册应与关闭时一致: %+v", got)
175		}
176	
177		// 销毁后的档案历史仍能看到最初截止日、最终截止日和按成功顺序
178		// 保留的两次修订；办理日期乱序也不改变顺序，与清册内容相符。
179		h1, found, err := s.History("A-1")
180		if err != nil || !found {
181			t.Fatalf("A-1 历史查询失败: found=%v err=%v", found, err)
182		}
183		if !h1.Destroyed || h1.ManifestApplicationID != "APP-1" {
184			t.Fatalf("A-1 应已销毁并归属 APP-1: %+v", h1)
185		}
186		if !h1.InitialEnd.Equal(initialEnd) || !h1.RetentionEnd.Equal(finalEnd) {
187			t.Fatalf("A-1 历史应保留最初截止日 %s 与最终截止日 %s: %+v", initialEnd, finalEnd, h1)
188		}
189		if len(h1.Revisions) != 2 {
190			t.Fatalf("A-1 应保留两次修订，得到 %d: %+v", len(h1.Revisions), h1.Revisions)
191		}
192		r1, r2 := h1.Revisions[0], h1.Revisions[1]
193		if r1.RevisionID != "R-1" || !r1.OldEnd.Equal(initialEnd) || !r1.NewEnd.Equal(extendedEnd) ||
194			!r1.RevisedOn.Equal(MustParseDate("2025-06-01")) || r1.Reason != "业务需要延长" {
195			t.Fatalf("第一条修订（延长）记录不符: %+v", r1)
196		}
197		if r2.RevisionID != "R-2" || !r2.OldEnd.Equal(extendedEnd) || !r2.NewEnd.Equal(finalEnd) ||
198			!r2.RevisedOn.Equal(MustParseDate("2024-12-01")) || r2.Reason != "重新评估缩短" {
199			t.Fatalf("第二条修订（缩短，办理日期更早）记录不符: %+v", r2)
200		}
201		if h1.Manifest == nil || h1.Manifest.ApplicationID != "APP-1" ||
202			len(h1.Manifest.Entries) != 2 || !h1.Manifest.Entries[0].End.Equal(finalEnd) {
203			t.Fatalf("A-1 历史附带的清册应与清册内容相符: %+v", h1.Manifest)
204		}
205	
206		h2, found, err := s.History("A-2")
207		if err != nil || !found {
208			t.Fatalf("A-2 历史查询失败: found=%v err=%v", found, err)
209		}
210		if !h2.Destroyed || h2.ManifestApplicationID != "APP-1" ||
211			!h2.InitialEnd.Equal(MustParseDate("2025-01-10")) ||
212			!h2.RetentionEnd.Equal(MustParseDate("2025-01-10")) || len(h2.Revisions) != 0 {
213			t.Fatalf("未修订的 A-2 历史不符: %+v", h2)
214		}
215		if h2.Manifest == nil || len(h2.Manifest.Entries) != 2 {
216			t.Fatalf("A-2 应与 A-1 在同一份清册中: %+v", h2.Manifest)
217		}
218	}
219	
220	// assertUndestroyed 断言名单中的每份档案都仍未销毁。
221	func assertUndestroyed(t *testing.T, s *Store, ids ...string) {
222		t.Helper()
223		for _, id := range ids {
224			h, found, err := s.History(id)
225			if err != nil || !found {
226				t.Fatalf("档案 %s 应仍可查询: found=%v err=%v", id, found, err)
227			}
228			if h.Destroyed || h.ManifestApplicationID != "" || h.Manifest != nil {
229				t.Fatalf("整批失败时档案 %s 不应被销毁或归入清册: %+v", id, h)
230			}
231		}
232	}
